reference_solution:
def is_square_sum(c):
    from math import isqrt
    left, right = 0, isqrt(c)
    while left <= right:
        value = left * left + right * right
        if value == c:
            return True
        if value < c:
            left += 1
        else:
            right -= 1
    return False

